bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createGateOwner} from '/opt/videobot/owner/gateOwner.mjs';
import {createPostgresListingStore} from '/opt/videobot/src/sales/pgListings.mjs';
import {createPostgresPostingReceiptStore} from '/opt/videobot/src/sales/pgPostingReceipts.mjs';
import {buildPaidMediaRequest} from '/opt/videobot/src/telegram/paidMedia.mjs';
const env=process.env;
const id='singlepaid4715_20261123', originalId=4715;
const dburl=env.VIDEOBOT_DATABASE_URL_FILE
 ?readPrivateToken(env.VIDEOBOT_DATABASE_URL_FILE)
 :'postgresql://'+encodeURIComponent(env.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+env.VIDEOBOT_DB_HOST+':5432/videobot';
const pool=new pg.Pool({connectionString:dburl,max:2,connectionTimeoutMillis:5000});
const net=createCreatorTelegramFetch(globalThis.fetch);
const api=createTelegramBotApi({token:readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000,baseUrl:env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
const key=id+':1';
let claimed=false;
try{
 const previous=await pool.query("SELECT l.*,r.free_message_ids,r.topic_id FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE r.paid_message_id=$1 AND r.status='sent' AND l.status='published'",[originalId]);
 if(previous.rowCount!==1)throw Error('ORIGINAL_LISTING_NOT_VERIFIED');
 const l=previous.rows[0],free=(l.free_message_ids??[]).map(Number);
 if(l.price_stars!==10||l.rights_verified!==true||l.adult_consent_verified!==true||
   !l.fee_terms_accepted_at||l.management_fee_bps!==3000||
   !l.paid_video_file_id||!l.thumbnail_file_id||!l.sample_file_id||
   free.length!==2||free[0]!==4712||free[1]!==4713||
   Number(l.topic_id)!==1695||Number(env.VIDEOBOT_VIDEO_SALE_THREAD_ID)!==1695)
   throw Error('ORIGINAL_PRICE_MEDIA_OR_CONSENT_CHANGED');
 const store=createPostgresPostingReceiptStore(pool);
 const prior=await store.read(key);
 if(prior){
   if(prior.status==='sent'&&Number.isSafeInteger(prior.paidMessageId)){
     console.log('ALREADY_SENT_PAID_ONLY='+prior.paidMessageId);
   }else throw Error('PAID_ONLY_PRIOR_ATTEMPT_NEEDS_RECONCILIATION');
 }else{
   await pool.query(
     "INSERT INTO videobot_listings (listing_id,seller_user_id,revision,title,description,price_stars,price_mode,thumbnail_file_id,sample_file_id,sample_duration_seconds,paid_video_file_id,rights_verified,adult_consent_verified,fee_terms_accepted_at,management_fee_bps,fee_policy_id,status) SELECT $1,seller_user_id,1,title,description,price_stars,price_mode,thumbnail_file_id,sample_file_id,sample_duration_seconds,paid_video_file_id,rights_verified,adult_consent_verified,fee_terms_accepted_at,management_fee_bps,fee_policy_id,'ready' FROM videobot_listings WHERE listing_id=$2 AND status='published' AND price_stars=10 AND rights_verified=TRUE AND adult_consent_verified=TRUE AND fee_terms_accepted_at IS NOT NULL AND management_fee_bps=3000 ON CONFLICT(listing_id) DO NOTHING",
     [id,l.listing_id]);
   const listings=createPostgresListingStore(pool);
   const clone=await listings.getOwned(Number(l.seller_user_id),id);
   if(!clone||clone.status!=='ready'||clone.revision!==1||
     clone.paidVideo?.fileId!==l.paid_video_file_id||
     clone.sample?.fileId!==l.sample_file_id||
     clone.thumbnail?.fileId!==l.thumbnail_file_id)
     throw Error('PAID_ONLY_SOURCE_MISMATCH');
   const owner=await createGateOwner({telegramApi:api,pool,env});
   const topic=await owner.getVerifiedVideoTopic({purpose:'video_sale',sellerId:clone.sellerId,listingId:id});
   if(!topic||topic.chatId!==-1002373696859||topic.threadId!==1695||
      topic.purpose!=='video_sale'||topic.enabled!==true||topic.verified!==true)
     throw Error('PAID_ONLY_TOPIC_INVALID');
   const caption=l.title+(l.description?'\n'+l.description:'');
   const request=buildPaidMediaRequest({chatId:topic.chatId,messageThreadId:topic.threadId,
     mediaFileId:clone.paidVideo.fileId,priceStars:10,caption,payload:key});
   if(request.media.length!==1||request.media[0].type!=='video'||
      request.star_count!==10||request.chat_id!==topic.chatId)
     throw Error('PAID_ONLY_REQUEST_INVALID');
   const claim=await store.claim({key,listingId:id,revision:1,topicId:topic.id??topic.threadId});
   if(!claim.claimed)throw Error('PAID_ONLY_EXISTING_CLAIM_DO_NOT_RESEND');
   claimed=true;
   // Reuse the two REAL pre-existing preview IDs as the receipt's reference,
   // but do not send a photo, sample, album, or any free video in this test.
   await store.recordFree(key,free);
   console.log('PAID_ONLY_SEND_METHOD=sendPaidMedia');
   const result=await api('sendPaidMedia',request);
   if(!Number.isSafeInteger(result?.message_id)||result.message_id<=0||
     result.chat?.id!==topic.chatId ||
     (result.message_thread_id!=null&&result.message_thread_id!==topic.threadId)||
     result.paid_media?.star_count!==10||
     !Array.isArray(result.paid_media?.paid_media)||
     result.paid_media.paid_media.length!==1||
     result.paid_media.paid_media[0]?.type!=='video')
      throw Error('PAID_ONLY_TELEGRAM_NATIVE_LOCK_ACK_INVALID');
   await store.recordPaid(key,result.message_id);
   const published=await pool.query("UPDATE videobot_listings SET status='published',revision=revision+1,updated_at=NOW() WHERE listing_id=$1 AND revision=1 AND status='ready' AND EXISTS (SELECT 1 FROM videobot_post_receipts r WHERE r.delivery_key=$2 AND r.status='sent' AND r.paid_message_id=$3) RETURNING listing_id",[id,key,result.message_id]);
   if(published.rowCount!==1)throw Error('PAID_ONLY_PUBLISH_STATUS_READBACK_FAILED');
   const after=await store.read(key);
   if(after?.status!=='sent'||after.paidMessageId!==result.message_id)
     throw Error('PAID_ONLY_RECEIPT_READBACK_FAILED');
   console.log('PAID_ONLY_NATIVE_STARS_SEND=PASS');
   console.log('PAID_ONLY_MESSAGE_ID='+result.message_id);
   console.log('PAID_ONLY_NEW_MEDIA_MESSAGES=1');
   console.log('PAID_ONLY_NEW_FREE_MEDIA_MESSAGES=0');
   console.log('EXISTING_MESSAGES_UNCHANGED=4691,4701,4714,4715');
 }
}catch(e){
 if(claimed)await pool.query("UPDATE videobot_post_receipts SET status='needs_reconcile' WHERE delivery_key=$1 AND status='sending'",[key]).catch(()=>{});
 console.error('PAID_ONLY_ERROR='+String(e?.message??'unknown').replace(/https?:\/\/\S+/g,'[redacted]').slice(0,130));
 process.exitCode=75;
}finally{await pool.end().catch(()=>{});await net.close().catch(()=>{});}
JS
